mapper.select:
SELECT id, word, phonetic, meaning_cn AS meaningCn, category, audio_url AS audioUrl
FROM user_vocabulary_entries
WHERE user_id = #{userId}
  AND id = #{entryId}
LIMIT 1

SELECT id, word, phonetic, meaning_cn AS meaningCn, category, audio_url AS audioUrl
FROM user_vocabulary_entries
WHERE user_id = #{userId} AND wordbook_id = #{wordbookId}
ORDER BY id ASC
LIMIT 1 OFFSET #{offset}

SELECT meaning_cn
FROM user_vocabulary_entries
WHERE user_id = #{userId}
  AND wordbook_id = #{wordbookId}
  AND id <> #{entryId}
ORDER BY RAND()
LIMIT 12

SELECT id, word, phonetic, meaning_cn AS meaningCn, category, audio_url AS audioUrl
FROM user_vocabulary_entries
WHERE user_id = #{userId}
  AND wordbook_id = #{wordbookId}
  AND id <> #{entryId}
ORDER BY id ASC
LIMIT 120
